update public.poetry as p
set body = x.body
from (
  select x->>'slug' as slug, x->>'body' as body
  from jsonb_array_elements($bodies$[{"slug":"tum-p006","body":"شوق تھا، تمنا تھی،  بےبسی ہے\nدرد اتنا ہے کہ کچھ نہی ہے\n\nوہ دور کہ خوب دلائل کے رد و بدل\nاور یہ حال کہ سب سہی سہی ہے\n\nآجکل زمیں پہ چاند کی روشنی کہاں ہے\nسچ مُچ چاند کی بھی کوئی روشنی ہے\n\nابھی ابھی تو ہم تم یہیں کہیں تھے\nاب بھی جہاں کہیں ہیں ، زندگی ہے\n\nخدا بھی باخدا  سب دیکھ رہا ہے احمد٘\nصحیح ہے جو اور نہیں ہے ، آدمی ہے"},{"slug":"tum-p007","body":"اگرچہ چپ چاپ یہ رویا بہت ہے\nدل کو تیری چاہت پہ بھروسہ بہت ہے\nشب بھر تو تیری یادوں کے جلتے رہے چراغ\nدن بھی تیری سوچوں میں گزرا بہت ہے\n\nکچھ بھی ممکن ہے ، توآئے یا نہ آئے لوٹ کے\nیا پھر یہ ہجر اور وصل کہ شامیں سب زیاں جائیں\nان میں شامل ہیں لہجوں کی تلخیاں تیرے لمس کی محک\nہم کو ایک بار بس یہ بتلا دے کہ ہم کہاں جائیں\n\nجائیں تو جائیں کہاں کہ جہاں تو نہ ہو\nکہ جہاں نہ ہو کوئی  سفر اور منزل نہ ہو\nاک راستہ باقی  ہے اور کوئی راستہ نہیں\nوہ جہاں میں نہ ہوں اور جہاں یہ دل نہ ہو\n\nتو میری جاں اے میرے درد کی مرہم\nمجھ کو چھو لے مجھے اپنا کردے\nمجھ سے چھین لے یہ ہجر کی تلخیاں ساری\nمجھ کو ایک لمحے میں غم سے بیگانہ کر دے\n\nمیرے سامنے آ میری آنکھوں میں دیکھ\nتیرے دہکتے ہوئے زخموں کی دوا ہوں میں\nتو نے خود اپنے لبوں سے کہا تھا چاند کی مثل\nاور یہ بھی کہا تھا کہ تیری ہوا ہوں میں\n\nمیں وہی احمد ہوں کہ جس کا نام تو نے\nدل کے ایک غوشے میں نہاں رکھا ہے\nمیں نے بھی ترے نام کی بھری ہے سیاہی\nاور ہر شعر میں ترا ذکرعیاں رکھا ہے\n\nذکر تیرے نازک لبوں کا تری زلفوں کی سیاہی کا\nذکر تیرے تیکھے ناک اور تیری پارسائی کا\nتیری جھکی جھکی نگاہوں کی شرمیلی شوخیاں\nتیری قربت کا قرار اور بے مثل مسیحائی کا\nیوں تو تیرے حسن کی تمسیلیں ہیں بہت\nپر کہنے کو تو یادوں کا بھی سہارہ بہت ہے\nتیری محبت کی کمی ہے مجھ میں بس احمد ؔ\nاور دل کو تیری چاہت پہ بھروسہ بہت ہے"},{"slug":"tum-p008","body":"بادصبا تجھ سے کہتے ہیں کہ ٹھہر ہی جائے گی\nیہ ہوا بنجر سے ہوتی ہوئی اس شہر ہی جائے گی\n\nڈھل گیا آفتاب ، شام چلی , دن گیا اور وہی ہم\nیہ گھڑی بھی آخر کو اے دل گزر ہی جائے گی"},{"slug":"tum-p009","body":"کوئی سوچ کا ساماں ہو جیس\nگل نہ ہو گلستاں ہو جیسے\n\nہر موڑ پہ رک جاتا ہوں\nمنزل بہت آساں ہو جیسے\n\nاس کی جیب میں رہتی ہے حُسن پری\nعشق زیرِ احساں ہو جیسے\n\nشاید کبھی تجھے ایسے بھولوں میں\nتو ہمیشہ سے انجاں ہو جیسے\n\nگزار رہا ہوں ہر پل اس طرح سے\nزندگی کارِ نالاں ہو جیسے\n\nجھانک رہے ہیں سبھی گریباں میں\nیہاں ہر شخص ہی نگراں ہو جیسے\n\nکئی دنوں سے تمہیں دیکھا نہیں\nکئی دن میرے رائیگاں ہو جیسے\n\nدیکھ رہا ہوں آسمان کو اس طرح\nاحمد ؔ  تو صاف نمایاں ہو جیسے"},{"slug":"tum-p010","body":"میں  خوف کے آخری دھانے پہ کھڑا\nیہ سوچتا ہوں کہ جو کبھی اب گرا\nتو نہ ہلوں گا نہ اٹھ پاؤں گا\nاندر ہی اندر ڈوبتا جاوں گا\nوہ جو دیپ ہے آخری امید کا\nنہیں خبر کہ کیا میں جلاوں گا\nمیں رنگ جس دعا کا تھا\nمیں  تھا جواب جس  صدا کا\nوہ سب ایک ڈھونگ تھا\nوہ سب کا سب سراب تھا\nوہ بس ایک شباب تھا\nوہ بس ایک خواب تھا\nوہ منزلوں کی بھوک تھی\nوہ سفر تو محض عذاب تھا\nمیں خوف کے ساحل پہ کھڑا\nکوئی ہے مجھ سے کہہ رہا\nتو نہ خوف کھا ، نہ  دل جلا\nاے بشر تو سنبھل جائے گا\nگرتا گرتا پہنچ جائے گا\nوقت کا کیا یہ ٹل جائے"}]$bodies$::jsonb) x
) as x
where p.slug = x.slug;
